import{_ as t,C as r,o as s,c as o,a2 as e,b as l,w as i,a as p,E as d,a3 as c}from"./chunks/framework.BC3NdntU.js";const q=JSON.parse('{"title":"7.3 协调与 Fiber(虚拟 DOM / 时间切片 / Lane)","description":"","frontmatter":{},"headers":[],"relativePath":"卷七-框架核心React/7.3-协调与Fiber.md","filePath":"卷七-框架核心React/7.3-协调与Fiber.md","lastUpdated":1788791186000}'),h={name:"卷七-框架核心React/7.3-协调与Fiber.md"};function u(g,a,k,b,E,m){const n=r("Mermaid");return s(),o("div",null,[a[1]||(a[1]=e(`<h1 id="_7-3-协调与-fiber-虚拟-dom-时间切片-lane" tabindex="-1">7.3 协调与 Fiber(虚拟 DOM / 时间切片 / Lane) <a class="header-anchor" href="#_7-3-协调与-fiber-虚拟-dom-时间切片-lane" aria-label="Permalink to &quot;7.3 协调与 Fiber(虚拟 DOM / 时间切片 / Lane)&quot;">​</a></h1><blockquote><p>卷:卷七 · 框架核心 · React 难度:⭐⭐⭐ 专家 | 阅读时间:25min</p></blockquote><hr><h2 id="一、协调-reconciliation-是什么" tabindex="-1">一、协调(Reconciliation)是什么 <a class="header-anchor" href="#一、协调-reconciliation-是什么" aria-label="Permalink to &quot;一、协调(Reconciliation)是什么&quot;">​</a></h2><p>状态更新后,React 要算出&quot;新旧 UI 的差异并更新 DOM&quot;,这个过程叫<strong>协调(Reconciliation)</strong>,核心是 <strong>Diff</strong>:</p><ul><li>同层比较,<code>type</code> 不同 → 整棵子树替换</li><li>列表用 <code>key</code> 复用节点</li></ul><div class="language-jsx vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// key 决定能否复用</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{list.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">x</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Item</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{x.id} {</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">x} /&gt;)}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><hr><h2 id="二、为什么从-栈-改成-fiber" tabindex="-1">二、为什么从&quot;栈&quot;改成 Fiber <a class="header-anchor" href="#二、为什么从-栈-改成-fiber" aria-label="Permalink to &quot;二、为什么从&quot;栈&quot;改成 Fiber&quot;">​</a></h2><p>早期 React 的协调是<strong>递归、一次性同步完成</strong>,任务大时<strong>长时间霸占主线程 → 卡顿</strong>。Fiber 把渲染拆成<strong>可中断、可恢复</strong>的小任务单元:</p>`,10)),(s(),l(c,null,{default:i(()=>[d(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BJS%20%E4%BB%BB%E5%8A%A1%5D%20--%3E%20B%5B%E5%8F%AF%E4%B8%AD%E6%96%AD%E7%82%B9%20check%5D%0A%20%20%20%20B%20--%3E%7C%E6%9C%89%E7%A9%BA%E9%97%B2%7C%20C%5B%E6%B8%B2%E6%9F%93%2F%E5%85%B6%E4%BB%96%E6%9B%B4%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%5D%0A%20%20%20%20B%20--%3E%7C%E6%97%B6%E9%97%B4%E7%89%87%E7%94%A8%E5%AE%8C%7C%20D%5B%E8%AE%A9%E5%87%BA%E4%B8%BB%E7%BA%BF%E7%A8%8B%2C%E4%B8%8B%E6%AC%A1%E7%BB%A7%E7%BB%AD%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e(`<ul><li><strong>Fiber</strong> = 一个任务的&quot;工作单元&quot;链表</li><li><strong>时间切片</strong>:每个时间片只处理一部分,时间到就让出,不阻塞输入</li></ul><hr><h2 id="三、双缓冲与优先级-lane" tabindex="-1">三、双缓冲与优先级(Lane) <a class="header-anchor" href="#三、双缓冲与优先级-lane" aria-label="Permalink to &quot;三、双缓冲与优先级(Lane)&quot;">​</a></h2><ul><li><strong>双缓冲</strong>:屏幕上当前树(current)+ 内存里正在构建的新树(workInProgress),构建完一次性切换,用户不会看到&quot;半成品&quot;</li><li><strong>Lane(车道)</strong>:用位运算给更新标优先级(如交互 &gt; 数据),高优先级更新能<strong>插队</strong>先处理(配合 <code>useTransition</code>)</li></ul><hr><h2 id="四、为什么需要-可中断渲染" tabindex="-1">四、为什么需要&quot;可中断渲染&quot; <a class="header-anchor" href="#四、为什么需要-可中断渲染" aria-label="Permalink to &quot;四、为什么需要&quot;可中断渲染&quot;&quot;">​</a></h2><blockquote><p>用户点击/输入是<strong>高优先级、需即时响应</strong>的,大量数据渲染是<strong>低优先级、可慢慢来</strong>的。如果一切同步串行,一次大更新就会卡住交互。Fiber 的&quot;可中断 + 优先级&quot;让 React 能&quot;<strong>先响应交互,再慢慢渲染大数据</strong>&quot;——这正是并发模式(7.4)的底座。</p></blockquote><hr><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Diff:同层比较 + key 复用</span></span>
<span class="line"><span>Fiber:可中断的工作单元链表,时间切片不阻塞主线程</span></span>
<span class="line"><span>双缓冲:current/新树切换,不闪屏</span></span>
<span class="line"><span>Lane:优先级调度(高优先插队)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="面试题" tabindex="-1">面试题 <a class="header-anchor" href="#面试题" aria-label="Permalink to &quot;面试题&quot;">​</a></h2><p><strong>Q1:Fiber 架构解决了什么问题?</strong></p><p>解决了&quot;一次性同步递归渲染导致<strong>主线程长时间被占用、页面卡顿</strong>&quot;的问题。它把渲染拆成<strong>可中断、可恢复</strong>的小任务 + 时间切片,让出主线程给用户交互,支持<strong>优先级调度</strong>(高优先任务插队)。</p><p><strong>Q2:<code>key</code> 在 React Diff 中的作用?为什么不能用 index?</strong></p><p><code>key</code> 用于判断新旧节点是否&quot;同一节点&quot;,能复用则复用、能移动则移动,最小化 DOM 操作。用 <code>index</code> 在列表增删时会导致后续节点被错误复用(状态/输入框串位),必须用稳定唯一 id。</p><hr><p>📎 参考:react.dev《Render and Commit》、React 官方《Fiber 深度解析》</p>`,17))])}const _=t(h,[["render",u]]);export{q as __pageData,_ as default};
